35	/// Default heartbeat / poll interval while a host CLI runs.
36	const DEFAULT_POLL_INTERVAL: Duration = Duration::from_secs(60);
37	/// Default wall-clock ceiling for a single host CLI invocation.
38	const DEFAULT_POLL_TIMEOUT: Duration = Duration::from_secs(60 * 60);
39	
40	/// Runtime configuration for [`HostCliHandDispatcher`].
41	#[derive(Clone, Debug)]
42	pub struct HostCliHandDispatcherConfig {
43	    /// When true, invoke the host CLI as part of dispatch; otherwise just
44	    /// record a note and leave the ticket `InFlight` for an operator.
45	    pub auto_dispatch: bool,
46	    /// Heartbeat interval (currently advisory; reserved for a future
47	    /// background poll loop).
48	    pub poll_interval: Duration,
49	    /// Wall-clock ceiling applied to the host CLI invocation.
50	    pub poll_timeout: Duration,
51	    /// Stable identity prefix used when minting hand ids.
52	    pub agent_identity: String,
53	    /// Prefix applied to dispatch branch names (`<prefix>/<batch>/<id>`).
54	    pub branch_prefix: String,
55	    /// Repository root used as the source for `git worktree add` (absolute).
56	    pub repo_root: PathBuf,
57	    /// Directory under which per-ticket worktrees are created (absolute).
58	    /// Each ticket gets its own checkout so concurrently dispatched host
59	    /// CLIs (codex/opencode/aider) never share an index or working tree.
60	    pub worktree_root: PathBuf,
61	    /// Whether to prepend Roughneck instructions to the prompt body.
62	    pub roughneck_enabled: bool,
63	    /// Roughneck level: "lite", "full", or "ultra".
64	    pub roughneck_level: String,
65	}
66	
67	impl Default for HostCliHandDispatcherConfig {
68	    fn default() -> Self {
69	        Self {
70	            auto_dispatch: true,
71	            poll_interval: DEFAULT_POLL_INTERVAL,
72	            poll_timeout: DEFAULT_POLL_TIMEOUT,
73	            agent_identity: "derrick-hand".to_owned(),
74	            branch_prefix: "derrick".to_owned(),
75	            repo_root: PathBuf::from("."),
76	            worktree_root: PathBuf::from(".derrick/host-worktrees"),
77	            roughneck_enabled: true,
78	            roughneck_level: "full".to_owned(),
79	        }
80	    }
81	}
