83	/// A [`HandDispatcher`] that drives a single named host CLI as a crew
84	/// executor. See the crate docs for the lifecycle contract.
85	pub struct HostCliHandDispatcher {
86	    substrate: Arc<NativeSubstrate>,
87	    hosts: Arc<HostRegistry>,
88	    host_name: &'static str,
89	    hand_kind: HandKind,
90	    model: Option<String>,
91	    config: HostCliHandDispatcherConfig,
92	}
93	
94	impl HostCliHandDispatcher {
95	    /// Construct a dispatcher for `host_name`, registering hands of
96	    /// `hand_kind` and passing `model` (RAW) to the host adapter.
97	    pub fn new(
98	        substrate: Arc<NativeSubstrate>,
99	        hosts: Arc<HostRegistry>,
100	        host_name: &'static str,
101	        hand_kind: HandKind,
102	        model: Option<String>,
103	        config: HostCliHandDispatcherConfig,
104	    ) -> Self {
105	        Self {
106	            substrate,
107	            hosts,
108	            host_name,
109	            hand_kind,
110	            model,
111	            config,
112	        }
113	    }
114	
115	    fn target_branch(&self, ticket: &Ticket) -> String {
116	        let batch = ticket
117	            .batch
118	            .as_ref()
119	            .map(derrick_substrate::BatchName::as_str)
120	            .unwrap_or("ad-hoc");
121	        format!("{}/{}/{}", self.config.branch_prefix, batch, ticket.id)
122	    }
123	
124	    fn mint_hand_id(&self) -> Result<HandId, SubstrateError> {
125	        // HandId pattern: ^[a-z][a-z0-9-]{0,63}$. Sanitize the configured
126	        // identity, then append a short suffix derived from the wall clock.
127	        let mut cleaned: String = self
128	            .config
129	            .agent_identity
130	            .chars()
131	            .filter_map(|c| {
132	                if c.is_ascii_alphanumeric() {
133	                    Some(c.to_ascii_lowercase())
134	                } else if c == '-' {
135	                    Some('-')
136	                } else {
137	                    None
138	                }
139	            })
140	            .collect();
141	        let starts_with_letter = cleaned
142	            .chars()
143	            .next()
144	            .map(|c| c.is_ascii_lowercase())
145	            .unwrap_or(false);
146	        if !starts_with_letter {
147	            cleaned.insert_str(0, "h-");
148	        }
149	        let suffix = short_suffix();
150	        let mut raw = format!("{cleaned}-{suffix}");
151	        raw.truncate(64);
152	        HandId::new(raw)
153	    }
154	
155	    /// Render the prompt body the host CLI receives. Inlined for MVP rather
156	    /// than depending on `derrick-claude`'s queue renderer. The branch is
157	    /// already checked out in `worktree`, so the agent works there directly
158	    /// rather than creating a branch itself.
159	    fn render_body(
160	        &self,
161	        ticket: &Ticket,
162	        branch: &str,
163	        parent_branch: &str,
164	        worktree: &std::path::Path,
165	    ) -> String {
166	        let batch_display = ticket
167	            .batch
168	            .as_ref()
169	            .map(derrick_substrate::BatchName::as_str)
170	            .unwrap_or("(none)");
171	        let worktree_display = worktree.display();
172	        let body = format!(
173	            "# Derrick ticket: {title}\n\n\
174	             You are implementing a ticket dispatched by derrick's crew-mode foreman.\n\
175	             Complete ALL steps below in order.\n\n\
176	             ## Ticket metadata\n\
177	             - **ID**: {id}\n\
178	             - **Batch**: {batch_display}\n\
179	             - **Branch**: `{branch}`\n\
180	             - **Base**: `{parent_branch}`\n\
181	             - **Worktree**: `{worktree_display}`\n\n\
182	             ## Specification\n\n{spec}\n\n\
183	             ## Required steps\n\n\
184	             1. Work inside the worktree `{worktree_display}`. The branch `{branch}` is\n   \
185	             already checked out there.\n\
186	             2. Implement the specification above and commit your changes.\n\
187	             3. Push the branch.\n\
188	             4. Run `derrick ticket review {id} --branch {branch} --head-sha <sha>`\n   \
189	             so the foreman's verifier can observe the merge. Do NOT mark the\n   \
190	             ticket done yourself.\n",
191	            title = ticket.title,
192	            id = ticket.id,
193	            spec = ticket.body,
194	        );
195	        if self.config.roughneck_enabled {
196	            derrick_roughneck::inject_prompt(&body, &self.config.roughneck_level)
197	        } else {
198	            body
199	        }
200	    }
201	
202	    /// Create the per-ticket worktree on `branch`, rooted at `parent_branch`,
203	    /// under `self.config.worktree_root`. Mirrors `LocalCopilotHandDispatcher`:
204	    /// each ticket gets its own checkout so concurrent host CLIs never share an
205	    /// index. Returns the worktree path on success.
206	    ///
207	    /// Lifecycle note: like `LocalCopilotHandDispatcher`, the worktree is created
208	    /// via raw `git worktree add` (not the substrate `reserve_worktree` row), so
209	    /// the foreman TTL pruning pass does not track it and the checkout persists
210	    /// after a *successful* dispatch. On failure it is removed (see `dispatch`).
211	    /// Adding success-path cleanup for both local hand dispatchers is a tracked
212	    /// follow-up; it is intentionally out of scope here so the two dispatchers
213	    /// stay behaviourally identical.
214	    async fn ensure_worktree(
215	        &self,
216	        ticket: &Ticket,
217	        branch: &str,
218	        parent_branch: &str,
219	    ) -> Result<PathBuf, DispatchError> {
220	        tokio::fs::create_dir_all(&self.config.worktree_root)
221	            .await
222	            .map_err(DispatchError::Io)?;
223	        let worktree_path = self.config.worktree_root.join(ticket.id.as_str());
224	        if !worktree_path.join(".git").exists() {
225	            let output = Command::new("git")
226	                .args(["worktree", "add", "-B", branch])
227	                .arg(&worktree_path)
228	                .arg(parent_branch)
229	                .current_dir(&self.config.repo_root)
230	                .kill_on_drop(true)
231	                .output()
232	                .await
233	                .map_err(DispatchError::Io)?;
234	            if !output.status.success() {
235	                let stderr = String::from_utf8_lossy(&output.stderr).trim().to_owned();
236	                return Err(DispatchError::Io(std::io::Error::other(format!(
237	                    "git worktree add failed: {stderr}"
238	                ))));
239	            }
240	        }
241	        Ok(worktree_path)
242	    }
243	
244	    /// Best-effort removal of a per-ticket worktree after a failed dispatch so
245	    /// the foreman cleanup pass (worktree_ttl) does not have to reclaim it.
246	    /// Logs but does not propagate failures.
247	    async fn cleanup_worktree(&self, worktree_path: &std::path::Path) {
248	        let result = Command::new("git")
249	            .args(["worktree", "remove", "--force"])
250	            .arg(worktree_path)
251	            .current_dir(&self.config.repo_root)
252	            .kill_on_drop(true)
253	            .output()
254	            .await;
255	        match result {
256	            Ok(output) if output.status.success() => {}
257	            Ok(output) => {
258	                let stderr = String::from_utf8_lossy(&output.stderr).trim().to_owned();
259	                warn!(
260	                    worktree = %worktree_path.display(),
261	                    %stderr,
262	                    "git worktree remove failed during host CLI cleanup"
263	                );
264	            }
265	            Err(error) => {
266	                warn!(
267	                    ?error,
268	                    worktree = %worktree_path.display(),
269	                    "failed to spawn git worktree remove during host CLI cleanup"
270	                );
271	            }
272	        }
273	    }
274	}
275	
276	fn short_suffix() -> String {
277	    use std::time::{SystemTime, UNIX_EPOCH};
278	    let nanos = SystemTime::now()
279	        .duration_since(UNIX_EPOCH)
280	        .map(|d| d.as_nanos())
281	        .unwrap_or(0);
282	    format!("{:06x}", (nanos as u64) & 0x00ff_ffff)
283	}
