285	#[async_trait]
286	impl HandDispatcher for HostCliHandDispatcher {
287	    fn kind(&self) -> &'static str {
288	        self.host_name
289	    }
290	
291	    #[instrument(skip(self, ctx), fields(ticket_id = %ctx.ticket.id, host = self.host_name))]
292	    async fn dispatch(&self, ctx: &DispatchContext<'_>) -> Result<DispatchResult, DispatchError> {
293	        let ticket = ctx.ticket;
294	        let branch = self.target_branch(ticket);
295	
296	        // 1. Mint and register the hand.
297	        let hand_id = self.mint_hand_id()?;
298	        self.substrate
299	            .register_hand(Hand {
300	                id: hand_id.clone(),
301	                kind: self.hand_kind,
302	                last_seen: Some(Utc::now()),
303	            })
304	            .await?;
305	
306	        // 2. Resolve the host adapter BEFORE assigning the ticket. A missing
307	        //    adapter must not leave the ticket stuck InFlight, so this check
308	        //    happens while the ticket is still Ready and unowned.
309	        let host = self.hosts.get(self.host_name).ok_or_else(|| {
310	            DispatchError::Substrate(SubstrateError::Invalid {
311	                field: "host".to_owned(),
312	                message: format!("host adapter {:?} is not registered", self.host_name),
313	            })
314	        })?;
315	
316	        // 3. Create the per-ticket worktree on the target branch, rooted at the
317	        //    foreman-supplied parent branch — also before assigning, so a git
318	        //    failure never strands the ticket InFlight. Concurrent host CLIs
319	        //    each get their own checkout (the core fix vs. the shared root).
320	        let worktree_path = self
321	            .ensure_worktree(ticket, &branch, &ctx.parent_branch)
322	            .await?;
323	
324	        // 4. Atomic Ready -> InFlight + owner = hand. From here every failure
325	        //    path must release the ticket and tear down the worktree.
326	        self.substrate.assign_to_hand(&ticket.id, &hand_id).await?;
327	
328	        // 5. Run the rest of dispatch with cleanup-on-error: any error after
329	        //    assignment releases the hand back to Ready and removes the
330	        //    worktree before propagating.
331	        let outcome = self
332	            .dispatch_assigned(ctx, &branch, &worktree_path, host)
333	            .await;
334	        if let Err(error) = outcome {
335	            let reason = format!("{} dispatch failed: {error}", self.host_name);
336	            warn!(ticket = %ticket.id, host = self.host_name, %reason, "host CLI dispatch failed");
337	            if let Err(release_error) = self
338	                .substrate
339	                .release_from_hand(&ticket.id, reason.clone())
340	                .await
341	            {
342	                warn!(
343	                    ?release_error,
344	                    ticket = %ticket.id,
345	                    "release_from_hand failed after host CLI error"
346	                );
347	            }
348	            let _ = self
349	                .record_note(ctx, format!("{} hand released: {reason}", self.host_name))
350	                .await;
351	            self.cleanup_worktree(&worktree_path).await;
352	            // Surface the failure to the foreman so it is NOT recorded as
353	            // dispatched (foreman.rs Phase 3). A released ticket is re-queued
354	            // on the next tick.
355	            return Err(error);
356	        }
357	
358	        Ok(DispatchResult {
359	            hand: hand_id,
360	            completed_synchronously: false,
361	        })
362	    }
363	}
364	
365	impl HostCliHandDispatcher {
366	    /// Post-assignment body. Any `Err` returned here triggers the caller's
367	    /// cleanup (release the hand + remove the worktree). The host CLI runs
368	    /// with `cwd` set to the per-ticket worktree so concurrent dispatches do
369	    /// not share a checkout or index.
370	    async fn dispatch_assigned(
371	        &self,
372	        ctx: &DispatchContext<'_>,
373	        branch: &str,
374	        worktree_path: &std::path::Path,
375	        host: &dyn derrick_tools::HostAdapter,
376	    ) -> Result<(), DispatchError> {
377	        let ticket = ctx.ticket;
378	
379	        // Build the host request. Model is RAW; the adapter normalises and
380	        // passes `--model` (D65). cwd is the per-ticket worktree.
381	        let body = self.render_body(ticket, branch, &ctx.parent_branch, worktree_path);
382	        let mut request = HostRequest::new(body, worktree_path);
383	        request.headless = true;
384	        request.model = self.model.clone();
385	        request.timeout = self.config.poll_timeout;
386	
387	        // If auto-dispatch is off, leave the ticket InFlight and surface a
388	        // note for the operator. The worktree is kept so the operator can run
389	        // the host CLI there.
390	        if !self.config.auto_dispatch {
391	            self.record_note(
392	                ctx,
393	                format!(
394	                    "{} hand: ticket {} assigned to a hand; worktree={}; \
395	                     auto-dispatch off, run the host CLI there manually",
396	                    self.host_name,
397	                    ticket.id,
398	                    worktree_path.display()
399	                ),
400	            )
401	            .await?;
402	            return Ok(());
403	        }
404	
405	        // Invoke the host CLI. A spawn error / timeout / nonzero exit surfaces
406	        // as `Err`, which the caller turns into a release + cleanup + Err so
407	        // the foreman does not record the ticket as dispatched.
408	        let response = host
409	            .run(request)
410	            .await
411	            .map_err(|error| DispatchError::Io(std::io::Error::other(error.to_string())))?;
412	
413	        let bytes_raw = (response.stdout.len().saturating_add(response.stderr.len())) as u32;
414	        let scrubber = derrick_scrub::Scrubber::with_defaults();
415	        let (_out, out_stats) = scrubber.scrub(self.host_name, response.stdout.as_bytes());
416	        let (_err, err_stats) = scrubber.scrub(self.host_name, response.stderr.as_bytes());
417	        let bytes_saved = out_stats
418	            .bytes_in
419	            .saturating_sub(out_stats.bytes_out)
420	            .saturating_add(err_stats.bytes_in.saturating_sub(err_stats.bytes_out))
421	            .min(u64::from(u32::MAX)) as u32;
422	        let roughneck_saved = if self.config.roughneck_enabled {
423	            derrick_roughneck::estimate_tokens_saved(
424	                response.tokens_out,
425	                &self.config.roughneck_level,
426	            )
427	        } else {
428	            0
429	        };
430	        self.record_note(
431	            ctx,
432	            format!(
433	                "{} hand stats: tokens_in={} tokens_out={} roughneck_saved={} \
434	                 bytes_raw={} bytes_saved={}",
435	                self.host_name,
436	                response.tokens_in,
437	                response.tokens_out,
438	                roughneck_saved,
439	                bytes_raw,
440	                bytes_saved
441	            ),
442	        )
443	        .await?;
444	        self.check_terminal_state(ctx).await;
445	        Ok(())
446	    }
447	
448	    async fn record_note(
449	        &self,
450	        ctx: &DispatchContext<'_>,
451	        body: String,
452	    ) -> Result<(), DispatchError> {
453	        self.substrate
454	            .record_typed_event(
455	                EventScope::Ticket(ctx.ticket.id.clone()),
456	                EventKind::Note { body },
457	            )
458	            .await?;
459	        Ok(())
460	    }
461	
462	    async fn check_terminal_state(&self, ctx: &DispatchContext<'_>) {
463	        match self.substrate.get_ticket(&ctx.ticket.id).await {
464	            Ok(Some(ticket)) => {
465	                if matches!(
466	                    ticket.state,
467	                    derrick_substrate::TicketState::InReview | derrick_substrate::TicketState::Done
468	                ) {
469	                    info!(
470	                        ticket = %ticket.id,
471	                        state = %ticket.state,
472	                        host = self.host_name,
473	                        "host CLI ticket reached terminal hand state"
474	                    );
475	                } else {
476	                    warn!(
477	                        ticket = %ticket.id,
478	                        state = %ticket.state,
479	                        host = self.host_name,
480	                        "host CLI exited but ticket is not InReview; operator may \
481	                         need to run `derrick ticket review`"
482	                    );
483	                }
484	            }
485	            Ok(None) => {
486	                warn!(ticket = %ctx.ticket.id, host = self.host_name, "ticket not found after host CLI exit");
487	            }
488	            Err(error) => {
489	                warn!(?error, ticket = %ctx.ticket.id, host = self.host_name, "failed to read ticket after host CLI exit");
490	            }
491	        }
492	    }
493	}
