581	    /// Initialise a minimal git repository in `dir` so `git worktree add` has
582	    /// something to operate against.
583	    fn init_repo(dir: &std::path::Path) {
584	        use std::process::Command as StdCommand;
585	        let run = |args: &[&str]| {
586	            let status = StdCommand::new("git")
587	                .args(args)
588	                .current_dir(dir)
589	                .status()
590	                .expect("git command");
591	            assert!(status.success(), "git {args:?} failed");
592	        };
593	        run(&["init", "-q", "-b", "main"]);
594	        run(&["config", "user.email", "test@example.invalid"]);
595	        run(&["config", "user.name", "Test"]);
596	        run(&["commit", "--allow-empty", "-q", "-m", "init"]);
