 let status = StdCommand::new("git")
.args(args)
.current_dir(dir)
.status()
.expect("git command");
 assert!(status.success(), "git {args:?} failed");
 };
 run(&["init", "-q", "-b", "main"]);
 run(&["config", "user.email", "test@example.invalid"]);
 run(&["config", "user.name", "Test"]);
 run(&["commit", "--allow-empty", "-q", "-m", "init"]);
 }

