32	/// Runtime configuration for [`LocalCopilotHandDispatcher`].
33	#[derive(Clone, Debug)]
34	pub struct LocalCopilotHandDispatcherConfig {
35	    /// When true, spawn `copilot` automatically; otherwise just write
36	    /// the queue file and leave invocation to an operator.
37	    pub auto_dispatch: bool,
38	    /// Heartbeat interval while the background task waits on `copilot`.
39	    pub poll_interval: Duration,
40	    /// Maximum wall-clock duration the background task waits before
41	    /// releasing the hand back to Ready.
42	    pub poll_timeout: Duration,
43	    /// Stable identity prefix used when minting hand ids.
44	    pub agent_identity: String,
45	    /// Prefix applied to dispatch branch names.
46	    pub branch_prefix: String,
