92	impl LocalCopilotHandDispatcher {
93	    /// Construct a dispatcher from its substrate and config.
94	    pub fn new(substrate: Arc<NativeSubstrate>, config: LocalCopilotHandDispatcherConfig) -> Self {
95	        Self {
96	            substrate,
97	            config,
98	            stack_backend: None,
