108	    fn target_branch(&self, ticket: &Ticket) -> String {
109	        let batch = ticket
110	            .batch
111	            .as_ref()
112	            .map(derrick_substrate::BatchName::as_str);
113	        branch_name(&self.config.branch_prefix, batch, ticket.id.as_str())
114	    }
115	
116	    fn mint_hand_id(&self) -> Result<HandId, SubstrateError> {
117	        let mut cleaned: String = self
118	            .config
119	            .agent_identity
120	            .chars()
121	            .filter_map(|c| {
122	                if c.is_ascii_alphanumeric() {
123	                    Some(c.to_ascii_lowercase())
124	                } else if c == '-' {
125	                    Some('-')
126	                } else {
127	                    None
128	                }
129	            })
130	            .collect();
131	        let starts_with_letter = cleaned
132	            .chars()
133	            .next()
134	            .map(|c| c.is_ascii_lowercase())
135	            .unwrap_or(false);
136	        if !starts_with_letter {
137	            cleaned.insert_str(0, "c-");
138	        }
139	        let suffix = short_suffix();
140	        let mut raw = format!("{cleaned}-{suffix}");
141	        raw.truncate(64);
142	        HandId::new(raw)
143	    }
144	}
145	
146	fn short_suffix() -> String {
147	    let nanos = SystemTime::now()
148	        .duration_since(UNIX_EPOCH)
149	        .map(|d| d.as_nanos())
150	        .unwrap_or(0);
151	    format!("{:06x}", (nanos as u64) & 0x00ff_ffff)
152	}
