154	/// Render the queue file content for a local copilot dispatch.
155	#[allow(clippy::too_many_arguments)]
156	fn render_queue_file(
157	    ticket_id: &str,
158	    batch: Option<&str>,
159	    title: &str,
160	    body: &str,
161	    branch: &str,
162	    parent_branch: &str,
163	    worktree: &std::path::Path,
164	    roughneck_enabled: bool,
165	    roughneck_level: &str,
166	) -> String {
167	    let batch_display = batch.unwrap_or("(none)");
168	    let mut out = String::new();
169	    out.push_str("# Derrick ticket: ");
170	    out.push_str(title);
171	    out.push('\n');
172	    out.push('\n');
173	    out.push_str(
174	        "You are implementing a ticket dispatched by derrick's crew-mode foreman.\n\
175	         Complete ALL steps below in order. Do not stop until the final review step is done.\n",
176	    );
177	    out.push('\n');
178	    out.push_str("## Ticket metadata\n");
179	    out.push_str(&format!("- **ID**: {ticket_id}\n"));
180	    out.push_str(&format!("- **Batch**: {batch_display}\n"));
181	    out.push_str(&format!("- **Branch**: `{branch}`\n"));
182	    out.push_str(&format!("- **Base**: `{parent_branch}`\n"));
183	    out.push_str(&format!("- **Worktree**: `{}`\n", worktree.display()));
184	    out.push('\n');
185	    out.push_str("## Specification\n\n");
186	    out.push_str(body);
187	    if !body.ends_with('\n') {
188	        out.push('\n');
189	    }
190	    out.push('\n');
191	    out.push_str("## Required steps\n\n");
192	    out.push_str(&format!(
193	        "1. Work inside the worktree `{}`. The branch `{branch}` is already checked out there.\n",
194	        worktree.display()
195	    ));
196	    out.push_str(
197	        "2. Implement the specification above. Commit all changes with conventional\n   \
198	         commit messages.\n",
199	    );
200	    out.push_str(&format!(
201	        "3. Push the branch: `git push -u origin {branch}`\n"
202	    ));
203	    out.push_str("4. Capture HEAD SHA: `git rev-parse HEAD`\n");
204	    out.push_str(&format!(
205	        "5. Hand back to the foreman:\n   `derrick ticket review {ticket_id} --branch {branch} --head-sha <HEAD_SHA>`\n",
206	    ));
207	    out.push('\n');
208	    out.push_str(
209	        "**Do not open a PR yourself** — the foreman handles PR creation when stacking\n\
210	         is configured.\n",
211	    );
212	    if roughneck_enabled {
213	        derrick_roughneck::inject_prompt(&out, roughneck_level)
214	    } else {
215	        out
216	    }
217	}
