219	#[async_trait]
220	impl HandDispatcher for LocalCopilotHandDispatcher {
221	    fn kind(&self) -> &'static str {
222	        "copilot"
223	    }
224	
225	    #[instrument(skip(self, ctx), fields(ticket_id = %ctx.ticket.id))]
226	    async fn dispatch(&self, ctx: &DispatchContext<'_>) -> Result<DispatchResult, DispatchError> {
227	        let ticket = ctx.ticket;
228	        let branch = self.target_branch(ticket);
229	
230	        // 1. Mint a hand id and register it.
231	        let hand_id = self.mint_hand_id()?;
232	        let hand = Hand {
233	            id: hand_id.clone(),
234	            kind: HandKind::Copilot,
235	            last_seen: Some(Utc::now()),
236	        };
237	        self.substrate.register_hand(hand).await?;
238	
239	        // 2. Create the per-ticket worktree on the target branch, rooted at
240	        //    the foreman-supplied parent branch.
241	        tokio::fs::create_dir_all(&self.config.worktree_root)
242	            .await
243	            .map_err(DispatchError::Io)?;
244	        let worktree_path = self.config.worktree_root.join(ticket.id.as_str());
245	        if !worktree_path.join(".git").exists() {
