248	                .arg(&worktree_path)
249	                .arg(&ctx.parent_branch)
250	                .current_dir(&self.config.repo_root)
251	                .kill_on_drop(true)
252	                .output()
253	                .await
254	                .map_err(DispatchError::Io)?;
255	            if !output.status.success() {
256	                let stderr = String::from_utf8_lossy(&output.stderr).trim().to_owned();
257	                return Err(DispatchError::Io(std::io::Error::other(format!(
258	                    "git worktree add failed: {stderr}"
259	                ))));
260	            }
261	        }
262	
263	        // 3. Render the queue file and write it.
264	        tokio::fs::create_dir_all(&self.config.queue_dir)
265	            .await
266	            .map_err(DispatchError::Io)?;
267	        let batch = ticket
268	            .batch
269	            .as_ref()
270	            .map(derrick_substrate::BatchName::as_str);
271	        let queue_body = render_queue_file(
272	            ticket.id.as_str(),
273	            batch,
274	            &ticket.title,
275	            &ticket.body,
276	            &branch,
277	            &ctx.parent_branch,
278	            &worktree_path,
279	            self.config.roughneck_enabled,
280	            &self.config.roughneck_level,
281	        );
282	        let queue_file = self
283	            .config
284	            .queue_dir
285	            .join(format!("{}.md", ticket.id.as_str()));
286	        tokio::fs::write(&queue_file, &queue_body)
287	            .await
288	            .map_err(DispatchError::Io)?;
289	
290	        // 4. Atomic Ready -> InFlight + owner = hand.
291	        self.substrate.assign_to_hand(&ticket.id, &hand_id).await?;
292	
293	        // 5. Surface dispatch in the activity log.
294	        let queue_path_display = queue_file.display().to_string();
295	        let worktree_display = worktree_path.display().to_string();
296	        let note = format!(
297	            "copilot (local) hand: queue={queue_path_display} worktree={worktree_display}; \
298	             will spawn `copilot -p <prompt> --add-dir {worktree_display}`"
299	        );
300	        self.substrate
301	            .record_typed_event(
302	                EventScope::Ticket(ticket.id.clone()),
303	                EventKind::Note { body: note },
304	            )
305	            .await?;
306	        info!(
307	            ticket = %ticket.id,
308	            branch = branch.as_str(),
309	            queue_file = %queue_path_display,
310	            worktree = %worktree_display,
311	            auto_dispatch = self.config.auto_dispatch,
312	            "local copilot queue file written"
313	        );
314	
315	        // 6. Optionally spawn the background poll task.
316	        if self.config.auto_dispatch {
317	            let task = PollTask {
318	                substrate: Arc::clone(&self.substrate),
319	                ticket_id: ticket.id.clone(),
320	                hand_id: hand_id.clone(),
321	                prompt: queue_body,
322	                worktree: worktree_path,
323	                repo_root: self.config.repo_root.clone(),
324	                branch: branch.clone(),
325	                parent_branch: ctx.parent_branch.clone(),
326	                copilot_binary: self.config.copilot_binary.clone(),
327	                allow_all_tools: self.config.allow_all_tools,
328	                poll_interval: self.config.poll_interval,
329	                poll_timeout: self.config.poll_timeout,
330	                roughneck_enabled: self.config.roughneck_enabled,
331	                roughneck_level: self.config.roughneck_level.clone(),
332	                stack_backend: self.stack_backend.clone(),
333	                stack_draft: self.config.stack_draft,
334	                agent_identity: self.config.agent_identity.clone(),
335	            };
336	            tokio::spawn(task.run());
337	        }
338	
339	        Ok(DispatchResult {
340	            hand: hand_id,
341	            completed_synchronously: false,
342	        })
343	    }
344	}
