346	/// Background task supervising a single `copilot` invocation.
347	struct PollTask {
348	    substrate: Arc<NativeSubstrate>,
349	    ticket_id: TicketId,
350	    hand_id: HandId,
351	    prompt: String,
352	    worktree: PathBuf,
353	    repo_root: PathBuf,
354	    branch: String,
355	    parent_branch: String,
356	    copilot_binary: PathBuf,
357	    allow_all_tools: bool,
358	    poll_interval: Duration,
359	    poll_timeout: Duration,
360	    roughneck_enabled: bool,
361	    roughneck_level: String,
362	    stack_backend: Option<Arc<dyn StackBackend>>,
363	    stack_draft: bool,
364	    agent_identity: String,
365	}
366	
367	impl PollTask {
368	    async fn run(self) {
369	        let mut cmd = Command::new(&self.copilot_binary);
370	        cmd.arg("-p")
371	            .arg(&self.prompt)
372	            .arg("--add-dir")
373	            .arg(&self.worktree)
374	            .stdin(Stdio::null())
375	            .stdout(Stdio::piped())
376	            .stderr(Stdio::piped())
377	            .kill_on_drop(true);
378	        if self.allow_all_tools {
379	            cmd.arg("--allow-all-tools");
380	        }
381	
382	        let mut child = match cmd.spawn() {
383	            Ok(child) => child,
384	            Err(error) => {
385	                error!(?error, "failed to spawn `copilot`");
386	                self.release(format!("failed to spawn copilot: {error}"))
387	                    .await;
388	                return;
389	            }
390	        };
391	
392	        let stdout_handle = child.stdout.take().map(|mut stdout| {
393	            tokio::spawn(async move {
394	                use tokio::io::AsyncReadExt;
395	                let mut buf = Vec::new();
396	                let _ = stdout.read_to_end(&mut buf).await;
397	                buf
398	            })
399	        });
400	
401	        let deadline = tokio::time::Instant::now() + self.poll_timeout;
402	        loop {
403	            if let Err(error) = self.substrate.hand_heartbeat(&self.hand_id).await {
404	                warn!(
405	                    ?error,
406	                    hand = %self.hand_id,
407	                    "hand_heartbeat failed during copilot poll loop"
408	                );
409	            }
410	
411	            let now = tokio::time::Instant::now();
412	            if now >= deadline {
413	                warn!(
414	                    ticket = %self.ticket_id,
415	                    timeout_seconds = self.poll_timeout.as_secs(),
416	                    "copilot dispatch timed out; killing process and releasing hand"
417	                );
418	                let _ = child.kill().await;
419	                self.release(format!(
420	                    "copilot dispatch timed out after {}s",
421	                    self.poll_timeout.as_secs()
422	                ))
423	                .await;
424	                return;
425	            }
426	
427	            let sleep = self
428	                .poll_interval
429	                .min(deadline.saturating_duration_since(now));
430	            tokio::select! {
431	                wait = child.wait() => {
432	                    match wait {
433	                        Ok(status) if status.success() => {
434	                            info!(
435	                                ticket = %self.ticket_id,
436	                                "copilot exited successfully"
437	                            );
438	                            let stdout_bytes = match stdout_handle {
439	                                Some(handle) => handle.await.unwrap_or_default(),
440	                                None => Vec::new(),
441	                            };
442	                            self.record_hand_stats(&stdout_bytes).await;
443	                            self.check_terminal_state().await;
444	                            self.open_stacked_pr().await;
445	                            return;
446	                        }
447	                        Ok(status) => {
448	                            warn!(
449	                                ticket = %self.ticket_id,
450	                                code = ?status.code(),
451	                                "copilot exited non-zero"
452	                            );
453	                            self.release(format!(
454	                                "copilot exited non-zero: {:?}",
455	                                status.code()
456	                            ))
457	                            .await;
458	                            return;
459	                        }
460	                        Err(error) => {
461	                            error!(?error, "failed to wait on copilot");
462	                            self.release(format!("failed to wait on copilot: {error}"))
463	                                .await;
464	                            return;
465	                        }
466	                    }
467	                }
468	                () = tokio::time::sleep(sleep) => {
469	                    // Loop back around for heartbeat + timeout check.
470	                }
471	            }
472	        }
473	    }
474	
475	    async fn record_hand_stats(&self, stdout_bytes: &[u8]) {
476	        let bytes_raw = stdout_bytes.len() as u32;
477	        let scrubber = derrick_scrub::Scrubber::with_defaults();
478	        let (_scrubbed, scrub_stats) = scrubber.scrub("copilot", stdout_bytes);
479	        let bytes_saved = scrub_stats
480	            .bytes_in
481	            .saturating_sub(scrub_stats.bytes_out)
482	            .min(u64::from(u32::MAX)) as u32;
483	
484	        // Copilot CLI does not currently emit structured token usage in
485	        // stdout, so input/output token counts are recorded as zero. The
486	        // scrub byte-savings + roughneck estimate remain meaningful.
487	        let tokens_in: u32 = 0;
488	        let tokens_out: u32 = 0;
489	        let roughneck_saved = if self.roughneck_enabled {
490	            derrick_roughneck::estimate_tokens_saved(tokens_out, &self.roughneck_level)
491	        } else {
492	            0
493	        };
494	
495	        let body = format!(
496	            "hand stats: tokens_in={tokens_in} tokens_out={tokens_out} \
497	             roughneck_saved={roughneck_saved} bytes_raw={bytes_raw} bytes_saved={bytes_saved}"
498	        );
499	        if let Err(error) = self
500	            .substrate
501	            .record_typed_event(
502	                EventScope::Ticket(self.ticket_id.clone()),
503	                EventKind::Note { body },
504	            )
505	            .await
506	        {
507	            warn!(?error, ticket = %self.ticket_id, "failed to record hand stats note");
508	        }
509	    }
510	
511	    async fn release(&self, reason: String) {
512	        if let Err(error) = self
513	            .substrate
514	            .release_from_hand(&self.ticket_id, reason.clone())
515	            .await
516	        {
517	            warn!(
518	                ?error,
519	                ticket = %self.ticket_id,
520	                reason = %reason,
521	                "release_from_hand failed during copilot cleanup"
522	            );
523	        }
524	        let _ = self
525	            .substrate
526	            .record_typed_event(
527	                EventScope::Ticket(self.ticket_id.clone()),
528	                EventKind::Note {
529	                    body: format!("copilot hand released: {reason}"),
530	                },
531	            )
532	            .await;
533	    }
534	
535	    async fn check_terminal_state(&self) {
536	        match self.substrate.get_ticket(&self.ticket_id).await {
537	            Ok(Some(ticket)) => {
538	                if matches!(
539	                    ticket.state,
540	                    derrick_substrate::TicketState::InReview | derrick_substrate::TicketState::Done
541	                ) {
542	                    info!(
543	                        ticket = %self.ticket_id,
544	                        state = %ticket.state,
545	                        "copilot ticket reached terminal hand state"
546	                    );
547	                } else {
548	                    warn!(
549	                        ticket = %self.ticket_id,
550	                        state = %ticket.state,
551	                        "copilot exited 0 but ticket is not InReview; \
552	                         operator may need to run `derrick ticket review`"
553	                    );
554	                }
555	            }
556	            Ok(None) => {
557	                warn!(ticket = %self.ticket_id, "ticket not found after copilot exit");
558	            }
559	            Err(error) => {
560	                warn!(?error, ticket = %self.ticket_id, "failed to read ticket after copilot exit");
561	            }
562	        }
563	    }
564	
565	    /// Open a stacked PR for this ticket's branch using the configured
566	    /// [`StackBackend`], then transition the ticket to `Done`. If the PR
567	    /// fails to open (e.g. nothing to diff, branch already has a PR), log a
568	    /// warning and leave the ticket in `InReview`.
569	    async fn open_stacked_pr(&self) {
570	        let Some(backend) = self.stack_backend.as_ref() else {
571	            return;
572	        };
573	
574	        let ticket = match self.substrate.get_ticket(&self.ticket_id).await {
575	            Ok(Some(t)) => t,
576	            Ok(None) => {
577	                warn!(ticket = %self.ticket_id, "ticket missing when opening stacked PR");
578	                return;
579	            }
580	            Err(error) => {
581	                warn!(?error, ticket = %self.ticket_id, "read ticket before open_pr failed");
582	                return;
583	            }
584	        };
585	        if ticket.state != TicketState::InReview {
586	            return;
587	        }
588	
589	        let metadata = self
590	            .substrate
591	            .most_recent_in_review_metadata(&self.ticket_id)
592	            .await
593	            .ok()
594	            .flatten();
595	        if let Some(m) = metadata.as_ref() {
596	            if m.pr_url.is_some() {
597	                return;
598	            }
599	        }
600	        let branch = metadata
601	            .as_ref()
602	            .map(|m| m.branch.clone())
603	            .unwrap_or_else(|| self.branch.clone());
604	        let head_sha_existing = metadata.as_ref().map(|m| m.head_sha.clone());
605	
606	        let body = format!("Closes {}\n\n{}", self.ticket_id, ticket.body);
607	        let params = OpenPrParams {
608	            branch: branch.clone(),
609	            parent_branch: self.parent_branch.clone(),
610	            title: ticket.title.clone(),
611	            body,
612	            draft: self.stack_draft,
613	            repo_root: self.repo_root.clone(),
614	        };
615	
616	        let info = match backend.open_pr(params).await {
617	            Ok(info) => info,
618	            Err(error) => {
619	                warn!(
620	                    ?error,
621	                    ticket = %self.ticket_id,
622	                    branch = %branch,
623	                    "gh pr create failed; leaving ticket in InReview"
624	                );
625	                let _ = self
626	                    .substrate
627	                    .record_typed_event(
628	                        EventScope::Ticket(self.ticket_id.clone()),
629	                        EventKind::Note {
630	                            body: format!("open_pr failed: {error}"),
631	                        },
632	                    )
633	                    .await;
634	                return;
635	            }
636	        };
637	
638	        let head_sha = if info.head_sha.is_empty() {
639	            head_sha_existing.unwrap_or_else(|| info.head_sha.clone())
640	        } else {
641	            info.head_sha.clone()
642	        };
643	        let new_metadata = InReviewMetadata {
644	            branch,
645	            pr_url: Some(info.url.clone()),
646	            pr_number: Some(info.number),
647	            head_sha,
648	        };
649	        if let Err(error) = self
650	            .substrate
651	            .transition_to_in_review(&self.ticket_id, new_metadata)
652	            .await
653	        {
654	            warn!(?error, ticket = %self.ticket_id, "failed to update InReview metadata with pr_url");
655	            return;
656	        }
657	
658	        match self
659	            .substrate
660	            .mark_ticket_done_manually(
661	                &self.ticket_id,
662	                ManualDoneAttestation {
663	                    claimant: self.agent_identity.clone(),
664	                    note: format!("copilot hand opened {}", info.url),
665	                },
666	            )
667	            .await
668	        {
669	            Ok(_) => {
670	                info!(
671	                    ticket = %self.ticket_id,
672	                    pr = %info.url,
673	                    "copilot hand opened stacked PR and marked ticket Done"
674	                );
675	            }
676	            Err(error) => {
677	                warn!(
678	                    ?error,
679	                    ticket = %self.ticket_id,
680	                    "mark_ticket_done_manually failed after PR open"
681	                );
682	            }
683	        }
684	    }
685	}
