885	        let deadline = std::time::Instant::now() + Duration::from_secs(3);
886	        let mut released = false;
887	        while std::time::Instant::now() < deadline {
888	            let refreshed = substrate
889	                .get_ticket(&ticket.id)
890	                .await
891	                .expect("get")
892	                .expect("present");
893	            if refreshed.state == TicketState::Ready && refreshed.owner.is_none() {
894	                released = true;
895	                break;
896	            }
897	            tokio::time::sleep(Duration::from_millis(40)).await;
898	        }
899	        assert!(released, "expected copilot poll task to release the hand");
900	    }
901	}
