.args(["worktree", "add", "-B", branch.as_str()])
.arg(&worktree_path)
.arg(&ctx.parent_branch)
.current_dir(&self.config.repo_root)
.kill_on_drop(true)
.output()
.await
.map_err(DispatchError::Io)?;
