 tokio::fs::create_dir_all(&self.config.queue_dir)
.await
.map_err(DispatchError::Io)?;
 let batch = ticket
.batch
.as_ref()
.map(derrick_substrate::BatchName::as_str);
 let queue_body = render_queue_file(
 ticket.id.as_str(),
 batch,
 &ticket.title,
 &ticket.body,
 &branch,
 &ctx.parent_branch,
 &worktree_path,
 self.config.roughneck_enabled,
 &self.config.roughneck_level,
 );
 let queue_file = self
.config
.queue_dir
.join(format!("{}.md", ticket.id.as_str()));
