fn hand_from_row(row: &rusqlite::Row<'_>) -> rusqlite::Result<Hand> {
 let id: String = row.get(0)?;
 let kind: String = row.get(1)?;
 let last_seen: Option<String> = row.get(2)?;
 Ok(Hand {
