 HostCliHandDispatcherConfig {
 auto_dispatch: true,
 poll_interval: Duration::from_millis(20),
 poll_timeout: Duration::from_millis(100),
 agent_identity: "codex-test".to_owned(),
 branch_prefix: "derrick".to_owned(),
 repo_root,
 worktree_root,
 roughneck_enabled: false,
